#include "climate/native/Tp357Decoder.h"

namespace growbox::app::climate_io::native {
namespace {

constexpr std::uint8_t kManufacturerDataType = 0xFFU;

bool parseCandidate(const std::uint8_t* data, std::size_t size, std::size_t offset,
                    Tp357Measurement& output) noexcept {
  if (data == nullptr || offset + 5U > size) {
    return false;
  }

  const std::uint8_t* payload = data + offset;
  const auto raw_temperature = static_cast<std::int16_t>(
      static_cast<std::uint16_t>(payload[1]) |
      (static_cast<std::uint16_t>(payload[2]) << 8U));
  const float temperature_c = static_cast<float>(raw_temperature) * 0.1F;
  const std::uint8_t humidity_pct = payload[3];
  const std::uint8_t battery_pct = payload[4];
  if (temperature_c < -50.0F || temperature_c > 100.0F || humidity_pct > 100U ||
      battery_pct > 100U) {
    return false;
  }

  output.temperature_c = temperature_c;
  output.relative_humidity_pct = static_cast<float>(humidity_pct);
  output.battery_pct = battery_pct;
  return true;
}

} // namespace

Tp357DecodeStatus decodeTp357Advertisement(const std::uint8_t* data, std::size_t size,
                                           Tp357Measurement& output) noexcept {
  output = {};
  if (data == nullptr || size == 0U) {
    return Tp357DecodeStatus::NotFound;
  }

  bool saw_manufacturer_data = false;
  bool saw_complete_candidate = false;
  std::size_t offset = 0U;
  while (offset < size) {
    const std::uint8_t field_length = data[offset];
    if (field_length == 0U) {
      break;
    }
    const std::size_t next_offset = offset + 1U + static_cast<std::size_t>(field_length);
    if (next_offset > size) {
      return Tp357DecodeStatus::MalformedAdvertisement;
    }
    if (field_length >= 1U && data[offset + 1U] == kManufacturerDataType) {
      saw_manufacturer_data = true;
      const std::uint8_t* manufacturer_data = data + offset + 2U;
      const std::size_t manufacturer_size = static_cast<std::size_t>(field_length - 1U);
      saw_complete_candidate = saw_complete_candidate || manufacturer_size >= 5U;

      Tp357Measurement decoded{};
      if (parseCandidate(manufacturer_data, manufacturer_size, 2U, decoded) ||
          parseCandidate(manufacturer_data, manufacturer_size, 0U, decoded)) {
        output = decoded;
        return Tp357DecodeStatus::Ok;
      }
    }
    offset = next_offset;
  }

  if (!saw_manufacturer_data) {
    return Tp357DecodeStatus::NotFound;
  }
  return saw_complete_candidate ? Tp357DecodeStatus::OutOfRange
                                : Tp357DecodeStatus::MalformedAdvertisement;
}

} // namespace growbox::app::climate_io::native
EOF
cat > test/test_tp357_decoder/test_main.cpp <<'EOF'
#include "climate/native/Tp357Decoder.h"

#include <array>
#include <cassert>
#include <cmath>
#include <cstdint>

using growbox::app::climate_io::native::decodeTp357Advertisement;
using growbox::app::climate_io::native::Tp357DecodeStatus;
using growbox::app::climate_io::native::Tp357Measurement;

namespace {

bool closeEnough(float left, float right) {
  return std::fabs(left - right) < 0.001F;
}

void testRealHardwareFrameOffsetZeroFallback() {
  constexpr std::array<std::uint8_t, 27> advertisement{{
      0x02U, 0x01U, 0x06U,
      0x0EU, 0x08U, 'T', 'P', '3', '5', '7', 'S', ' ', '(', '7', '6', '2', '0', ')',
      0x08U, 0xFFU, 0xC2U, 0xECU, 0x00U, 0x4AU, 0x22U, 0x0BU, 0x01U,
  }};
  Tp357Measurement decoded{};
  assert(decodeTp357Advertisement(advertisement.data(), advertisement.size(), decoded) ==
         Tp357DecodeStatus::Ok);
  assert(closeEnough(decoded.temperature_c, 23.6F));
  assert(closeEnough(decoded.relative_humidity_pct, 74.0F));
  assert(decoded.battery_pct == 34U);
}

void testRealHardwareTemperatureChanges() {
  constexpr std::array<std::uint8_t, 27> advertisement{{
      0x02U, 0x01U, 0x06U,
      0x0EU, 0x08U, 'T', 'P', '3', '5', '7', 'S', ' ', '(', '7', '6', '2', '0', ')',
      0x08U, 0xFFU, 0xC2U, 0xEBU, 0x00U, 0x4AU, 0x22U, 0x0BU, 0x01U,
  }};
  Tp357Measurement decoded{};
  assert(decodeTp357Advertisement(advertisement.data(), advertisement.size(), decoded) ==
         Tp357DecodeStatus::Ok);
  assert(closeEnough(decoded.temperature_c, 23.5F));
}

void testLiteGraphOffsetTwoFixture() {
  constexpr std::array<std::uint8_t, 20> advertisement{{
      0x02U, 0x01U, 0x06U,
      0x06U, 0x09U, 'T', 'P', '3', '5', '7',
      0x09U, 0xFFU, 0x34U, 0x12U, 0x10U, 0xE8U, 0x00U, 0x32U, 0x64U, 0x00U,
  }};
  Tp357Measurement decoded{};
  assert(decodeTp357Advertisement(advertisement.data(), advertisement.size(), decoded) ==
         Tp357DecodeStatus::Ok);
  assert(closeEnough(decoded.temperature_c, 23.2F));
  assert(closeEnough(decoded.relative_humidity_pct, 50.0F));
  assert(decoded.battery_pct == 100U);
}

void testMalformedAndOutOfRangeAreRejected() {
  constexpr std::array<std::uint8_t, 4> truncated{{0x03U, 0xFFU, 0x01U, 0x02U}};
  Tp357Measurement decoded{};
  assert(decodeTp357Advertisement(truncated.data(), truncated.size(), decoded) ==
         Tp357DecodeStatus::MalformedAdvertisement);

  constexpr std::array<std::uint8_t, 7> invalid{{
      0x06U, 0xFFU, 0x00U, 0xFFU, 0x7FU, 0x65U, 0x65U,
  }};
  assert(decodeTp357Advertisement(invalid.data(), invalid.size(), decoded) ==
         Tp357DecodeStatus::OutOfRange);
}

} // namespace

int main() {
  testRealHardwareFrameOffsetZeroFallback();
  testRealHardwareTemperatureChanges();
  testLiteGraphOffsetTwoFixture();
  testMalformedAndOutOfRangeAreRejected();
  return 0;
}
